+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.router.NavigationTrigger;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.theme.lumo.LumoUtility;
+import org.slf4j.LoggerFactory;
+
+import java.util.function.Supplier;
+import java.util.stream.Stream;
+
+/** UC-002: View Veterinarians. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetsView extends VerticalLayout {
+
+    private final transient VetRepository repository;
+
+    public VetsView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+
+        H2 heading = new H2("Veterinarians");
+        heading.addClassNames(LumoUtility.Margin.NONE);
+
+        Grid<Vet> grid = new Grid<>();
+        grid.setAriaLabel("Veterinarians");
+        grid.setSelectionMode(Grid.SelectionMode.NONE);
+        grid.addColumn(Vet::firstName).setHeader("First Name").setKey("firstName");
+        grid.addColumn(Vet::lastName).setHeader("Last Name").setKey("lastName");
+        grid.addColumn(vet -> vet.specialties().isEmpty()
+                        ? "none" : String.join(", ", vet.specialties()))
+                .setHeader("Specialties").setKey("specialties");
+        grid.setItems(
+                query -> load(() -> this.repository.findPage(query.getOffset(), query.getLimit()), Stream.empty()),
+                query -> load(() -> this.repository.count(), 0));
+        grid.setSizeFull();
+
+        add(heading, grid);
+        expand(grid);
+    }
+
+    private <T> T load(Supplier<T> query, T emptyResult) {
+        try {
+            return query.get();
+        } catch (RuntimeException failure) {
+            // Lazy callbacks run after navigation, outside the router's normal
+            // exception handling. Route failures through the same error view.
+            LoggerFactory.getLogger(VetsView.class).error("Unable to load veterinarians", failure);
+            removeAll();
+            UI ui = UI.getCurrent();
+            ui.getInternals().getRouter().handleExceptionNavigation(ui,
+                    ui.getInternals().getActiveViewLocation(), failure,
+                    NavigationTrigger.PROGRAMMATIC, null);
+            return emptyResult;
+        }
+    }
+}
